head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeMultiFocus]<br/>Body Cell 의 위치정보 객체를 사용하여 불연속적인 Cell 의 포커스 상태를 해제합니다.",
    "validation" : [
        "cellsPosition(필수) 파라미터로 전달한 Body Cell 위치정보 객체 배열로 불연속적인 Cell 들의 포커스 상태를 해제합니다.",
        "cellsPosition(필수) 배열의 각 요소가 단일 Cell { row, col } 형식이면 해당 Cell 1개의 포커스를 해제합니다. (row 는 0 부터 표시된 Row 기준, col 은 0 부터 숨겨진 Column 을 포함한 인덱스)",
        "cellsPosition(필수) 배열의 각 요소가 범위 Cell { startRow, startCol, endRow, endCol } 형식이면 해당 사각 영역의 모든 Cell 의 포커스를 해제합니다.",
        "cellsPosition(필수) 배열에 단일 Cell 과 범위 Cell 을 혼합하여 설정할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - focusMode 는 'cell' 로 고정 (removeMultiFocus 는 Cell 포커스 해제 메소드)
//  - selectedCellColor(red) 로 포커스 결과를 배경색으로 구분 → 해제된 Cell 은 색이 빠짐
//  - 8 Row, 4 Column.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="focusMode=cell / selectedCellColor=red (포커스된 Cell), 해제된 Cell 은 배경색이 사라짐)"', '', 'label1');

    // dataList 생성 (4 Column, 8 Row 직접 구성)
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strData += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strData += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let i = 1; i <= 8; i++) {
        jsonData.push({
            "col1" : "c1_" + i, "col2" : "c2_" + i, "col3" : "c3_" + i, "col4" : "c4_" + i
        });
    }
    dlt_bind.setJSON(jsonData);

    // 조건 설정
    let properties = {
        focusMode         : "cell",
        selectedCellColor : "red"
    };
    let cList = $c.gcm.createCList(properties);

    let eList = "";

    // target 생성 (4 Column)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" useShiftKey="true" checkAllType="false" id="" style="width:420px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="removeMultiFocus 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="col0"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="col1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="col2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 공통 실행 함수
//  1) 선행: setMultiFocus 로 넓은 범위(Row 0~5, Col 0~3) 의 Cell 들을 먼저 포커스
//  2) removeMultiFocus(removePosition) 로 시나리오 Cell/범위 해제
//  3) 출력: 선행 포커스 개수 → 해제 대상 → 해제 후 남은 포커스 Cell 목록/개수
//  - 남은 포커스가 줄었음을 확인하여 지정 Cell 이 해제되었음을 검증
scwin.runRemoveMultiFocus = function (title, removePosition) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[" + title + "]");

    // 기존 포커스 제거 후 시작
    target1.removeFocusedCell();

    // 선행: 넓은 범위 포커스 (Row 0~5, Col 0~3 = 24 Cell)
    target1.setMultiFocus([ { startRow : 0, startCol : 0, endRow : 5, endCol : 3 } ]);
    let before = target1.getAllFocusedIndex();
    bottom.setReturnValue("선행 포커스(setMultiFocus 범위 0,0~5,3) → 포커스 셀 " + before.length + "개");

    // 해제 실행
    bottom.setReturnValue("removeMultiFocus cellsPosition = " + JSON.stringify(removePosition));
    target1.removeMultiFocus(removePosition);

    let after = target1.getAllFocusedIndex();
    bottom.setReturnValue("해제 후 getAllFocusedIndex = " + JSON.stringify(after));
    bottom.setReturnValue("해제 후 남은 포커스 셀 " + after.length + "개 (선행 " + before.length + "개 → " + (before.length - after.length) + "개 해제)");
}



// removeMultiFocus 실행 : par_scenario 선택값으로 분기
scwin.btn_run_onclick = function () {
    let scenario = par_scenario.getValue();

    switch (scenario) {
        case "single" :
            // 1) 단일 Cell 해제 : 선행 다수 포커스 → [{row:1,col:0}] 1개 해제
            scwin.runRemoveMultiFocus("단일 Cell 해제", [ { row : 1, col : 0 } ]);
            break;
        case "range" :
            // 2) 범위 Cell 해제 : 선행 다수 포커스 → 사각 영역(3,2~4,3) 해제
            scwin.runRemoveMultiFocus("범위 Cell 해제 {startRow:3,startCol:2,endRow:4,endCol:3}", [ { startRow : 3, startCol : 2, endRow : 4, endCol : 3 } ]);
            break;
        case "mixed" :
            // 3) 단일 + 범위 혼합 해제
            scwin.runRemoveMultiFocus("단일 + 범위 혼합 해제", [ { row : 0, col : 0 }, { row : 2, col : 3 }, { startRow : 4, startCol : 1, endRow : 5, endCol : 2 } ]);
            break;
    }
}
